public static char FirstNonRepeatedCharacter(string input)
{
    var counts = new Dictionary<char, int>();
    foreach (char c in input)
        counts[c] = counts.GetValueOrDefault(c) + 1; // pass 1: count

    foreach (char c in input) // pass 2: original order
        if (counts[c] == 1)
            return c;

    return '\0'; // no non-repeated character found
}

