public static string Reverse(string input)
{
    char[] arr = input.ToCharArray(); // strings are immutable
    int l = 0, r = arr.Length - 1;
    while (l < r)
    {
        (arr[l], arr[r]) = (arr[r], arr[l]);
        l++;
        r--;
    }
    return new string(arr);
}

