public static int MaxProfit(int[] prices)
{
    int minPrice = int.MaxValue, maxProfit = 0;
    foreach (int p in prices)
    {
        if (p < minPrice) minPrice = p;
        else if (p - minPrice > maxProfit) maxProfit = p - minPrice;
    }
    return maxProfit;
}

