public static int[] PlusOne(int[] digits)
{
    for (int i = digits.Length - 1; i >= 0; i--)
    {
        if (digits[i] < 9)
        {
            digits[i]++;
            return digits;
        }
        digits[i] = 0; // 9 -> 0, carry left
    }
    // All digits were 9 (e.g., 999 -> 1000)
    var result = new int[digits.Length + 1];
    result[0] = 1;
    return result;
}

