public static int RomanToInt(string s)
{
    var map = new Dictionary<char, int>
    {
        ['I'] = 1, ['V'] = 5, ['X'] = 10, ['L'] = 50,
        ['C'] = 100, ['D'] = 500, ['M'] = 1000
    };
    int total = 0;
    for (int i = 0; i < s.Length; i++)
    {
        int cur = map[s[i]];
        if (i + 1 < s.Length && cur < map[s[i + 1]])
            total -= cur; // e.g. I before V means subtract: IV = 4
        else
            total += cur;
    }
    return total;
}

