public class ListNode
{
    public int val;
    public ListNode next;
    public ListNode(int val = 0, ListNode next = null) { this.val = val; this.next = next; }
}

// Reverse (THE most asked)
public static ListNode Reverse(ListNode head)
{
    ListNode prev = null, cur = head;
    while (cur != null)
    {
        var next = cur.next;
        cur.next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

// Detect a cycle -- Floyd's slow/fast
public static bool HasCycle(ListNode head)
{
    ListNode slow = head, fast = head;
    while (fast?.next != null)
    {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) return true;
    }
    return false;
}

// Merge two sorted lists -- dummy head
public static ListNode MergeTwoLists(ListNode l1, ListNode l2)
{
    ListNode dummy = new ListNode(), tail = dummy;
    while (l1 != null && l2 != null)
    {
        if (l1.val <= l2.val) { tail.next = l1; l1 = l1.next; }
        else { tail.next = l2; l2 = l2.next; }
        tail = tail.next;
    }
    tail.next = l1 ?? l2;
    return dummy.next;
}

// Remove Nth from end -- fast pointer n steps ahead
public static ListNode RemoveNthFromEnd(ListNode head, int n)
{
    var dummy = new ListNode(0, head);
    ListNode fast = dummy, slow = dummy;
    for (int i = 0; i < n; i++) fast = fast.next;
    while (fast.next != null) { fast = fast.next; slow = slow.next; }
    slow.next = slow.next.next;
    return dummy.next;
}

// Move zeroes (keep relative order) -- O(n)/O(1)
public static void MoveZeroes(int[] nums)
{
    int insert = 0;
    for (int i = 0; i < nums.Length; i++)
        if (nums[i] != 0) nums[insert++] = nums[i];
    while (insert < nums.Length) nums[insert++] = 0;
}

// Kadane's max subarray sum
public static int MaxSubArray(int[] nums)
{
    int current = nums[0], best = nums[0];
    for (int i = 1; i < nums.Length; i++)
    {
        current = Math.Max(nums[i], current + nums[i]);
        best = Math.Max(best, current);
    }
    return best;
}
