// Rotate right by k -- triple reversal, O(n)/O(1)
public static void Rotate(int[] nums, int k)
{
    int n = nums.Length;
    k %= n;
    Reverse(nums, 0, n - 1);
    Reverse(nums, 0, k - 1);
    Reverse(nums, k, n - 1);
}
static void Reverse(int[] a, int l, int r)
{
    while (l < r) { (a[l], a[r]) = (a[r], a[l]); l++; r--; }
}

// Second largest -- one pass
public static int SecondLargest(int[] nums)
{
    long first = long.MinValue, second = long.MinValue;
    foreach (int n in nums)
    {
        if (n > first) { second = first; first = n; }
        else if (n > second && n != first) { second = n; }
    }
    return (int)second;
}

// Merge two sorted arrays in place -- fill from the BACK
public static void Merge(int[] nums1, int m, int[] nums2, int n)
{
    int i = m - 1, j = n - 1, k = m + n - 1;
    while (j >= 0)
    {
        nums1[k--] = (i >= 0 && nums1[i] > nums2[j]) ? nums1[i--] : nums2[j--];
    }
}

// Valid anagram -- count up with s, count down with t
public static bool IsAnagram(string s, string t)
{
    if (s.Length != t.Length) return false;
    var counts = new Dictionary<char, int>();
    foreach (char c in s) counts[c] = counts.GetValueOrDefault(c) + 1;
    foreach (char c in t)
    {
        if (!counts.ContainsKey(c) || counts[c] == 0) return false;
        counts[c]--;
    }
    return true;
}

// Group anagrams -- key = sorted letters ("eat","tea","ate" -> "aet")
public static List<List<string>> GroupAnagrams(string[] strs)
{
    var groups = new Dictionary<string, List<string>>();
    foreach (var word in strs)
    {
        var key = new string(word.OrderBy(c => c).ToArray());
        if (!groups.ContainsKey(key)) groups[key] = new List<string>();
        groups[key].Add(word);
    }
    return groups.Values.ToList();
}

// Word frequency
public static Dictionary<string, int> WordFrequency(string text) =>
    text.Split(' ', StringSplitOptions.RemoveEmptyEntries)
        .GroupBy(w => w)
        .ToDictionary(g => g.Key, g => g.Count());

// Majority element -- Boyer-Moore voting, O(n)/O(1)
public static int MajorityElement(int[] nums)
{
    int cand = 0, votes = 0;
    foreach (int n in nums)
    {
        if (votes == 0) cand = n;
        votes += (n == cand) ? 1 : -1;
    }
    return cand;
}

// Intersection -- HashSet lookup
public static int[] Intersection(int[] a, int[] b)
{
    var setA = new HashSet<int>(a);
    return setA.Intersect(b).ToArray();
}

